<script setup lang="ts">import{ref}from'vue';import{ClipboardCheck,Plus,Save}from'@lucide/vue';const points=ref([{point:'零点',expected:0,actual:0},{point:'量程中点',expected:50,actual:50},{point:'满量程',expected:100,actual:100}]);const saving=ref(false);function add(){points.value.push({point:'',expected:0,actual:0})}</script><template><section><div class="page-title"><div><h1>校准执行</h1><p>登记实测结果、执行证据并提交独立复核</p></div><button class="primary" :disabled="saving"><Save :size="17"/>保存执行记录</button></div><div class="form-band"><div class="field"><label>仪器编号</label><input placeholder="选择待校准仪器"></div><div class="field"><label>校准项目</label><input placeholder="选择适用项目"></div><div class="field"><label>执行人员</label><input value="本地校准员"></div><div class="field"><label>完成时间</label><input type="datetime-local"></div></div><div class="section-heading"><div><ClipboardCheck :size="19"/><strong>测量点</strong></div><button class="quiet" @click="add"><Plus :size="16"/>增加测量点</button></div><div class="table-wrap"><table><thead><tr><th>测量点</th><th>标准值</th><th>实测值</th><th>误差</th><th>判定</th></tr></thead><tbody><tr v-for="(point,index) in points" :key="index"><td><input v-model="point.point"></td><td><input v-model.number="point.expected" type="number"></td><td><input v-model.number="point.actual" type="number"></td><td>{{Math.abs(point.actual-point.expected).toFixed(3)}}</td><td><span class="badge" :class="Math.abs(point.actual-point.expected)<=0.5?'badge-qualified':'badge-unqualified'">{{Math.abs(point.actual-point.expected)<=0.5?'通过':'超差'}}</span></td></tr></tbody></table></div></section></template>

